import{_ as a,o,c as r,a3 as s}from"./chunks/framework.Cc-oPviL.js";const g=JSON.parse('{"title":"01 · GIL 与多线程：Python 为什么「多线程不快」","description":"","frontmatter":{},"headers":[],"relativePath":"bagu/python/01.md","filePath":"bagu/python/01.md"}'),l={name:"bagu/python/01.md"};function n(e,t,d,i,h,u){return o(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="_01-·-gil-与多线程-python-为什么「多线程不快」" tabindex="-1">01 · GIL 与多线程：Python 为什么「多线程不快」 <a class="header-anchor" href="#_01-·-gil-与多线程-python-为什么「多线程不快」" aria-label="Permalink to &quot;01 · GIL 与多线程：Python 为什么「多线程不快」&quot;">​</a></h1><blockquote><p><strong>学完你能说出</strong>：</p><ul><li>GIL 是什么：同一时刻只允许一个线程执行 Python 字节码。</li><li>为什么 IO 密集型任务用多线程仍然有效，CPU 密集型却没用。</li><li>CPU 密集型任务该用什么：多进程。</li></ul></blockquote><h2 id="先看地图" tabindex="-1">先看地图 <a class="header-anchor" href="#先看地图" aria-label="Permalink to &quot;先看地图&quot;">​</a></h2><p>这是「Python 与工程」模块的第一篇，接着<a href="/study-hub/bagu/os/01">进程与线程</a>讲。操作系统篇讲的是通用原理，这一篇讲 <strong>Python 特有的一个限制</strong>。AI 应用岗面试问 Python，这题出现频率最高。</p><p>本篇讲 4 个点：① GIL 是什么 → ② 为什么有 GIL → ③ IO 密集 vs CPU 密集 → ④ 怎么选：线程、进程、协程。</p><h2 id="一句话本质" tabindex="-1">一句话本质 <a class="header-anchor" href="#一句话本质" aria-label="Permalink to &quot;一句话本质&quot;">​</a></h2><p><strong>GIL（全局解释器锁）= CPython 解释器里的一把大锁：同一时刻，只有拿到锁的那个线程能执行 Python 代码。</strong></p><h2 id="生活类比-只有一支麦克风的会议" tabindex="-1">生活类比：只有一支麦克风的会议 <a class="header-anchor" href="#生活类比-只有一支麦克风的会议" aria-label="Permalink to &quot;生活类比：只有一支麦克风的会议&quot;">​</a></h2><ul><li>会议室里有 4 个人（4 个线程），但<strong>只有一支麦克风</strong>（GIL）。谁拿着麦克风谁才能说话。</li><li>如果大家都要一直说话（<strong>CPU 密集</strong>：一直在算），4 个人轮流用麦克风，总的说话时间和 1 个人差不多，<strong>没有变快</strong>。</li><li>如果大家大部分时间在<strong>等别人回邮件</strong>（<strong>IO 密集</strong>：等网络、等磁盘），等的时候把麦克风放下，别人就能用。<strong>4 个人一起等，总时间大大缩短。</strong></li></ul><h2 id="一步步看-两个实验-数字是示意" tabindex="-1">一步步看：两个实验（数字是示意） <a class="header-anchor" href="#一步步看-两个实验-数字是示意" aria-label="Permalink to &quot;一步步看：两个实验（数字是示意）&quot;">​</a></h2><p><strong>实验 1：CPU 密集</strong>：计算 1 到 1 亿的平方和，做 4 次。</p><table tabindex="0"><thead><tr><th>方式</th><th>耗时</th></tr></thead><tbody><tr><td>单线程，顺序做 4 次</td><td>约 20 秒</td></tr><tr><td>4 个线程</td><td>约 20 秒（甚至更慢，因为切换线程有开销）</td></tr><tr><td>4 个进程</td><td>约 5 秒（4 核 CPU 真正同时算）</td></tr></tbody></table><p><strong>实验 2：IO 密集</strong>：请求 4 个网页，每个要等 1 秒。</p><table tabindex="0"><thead><tr><th>方式</th><th>耗时</th></tr></thead><tbody><tr><td>单线程，顺序请求</td><td>约 4 秒</td></tr><tr><td>4 个线程</td><td>约 1 秒</td></tr></tbody></table><p>为什么实验 2 有效？线程在<strong>等网络</strong>时会<strong>主动释放 GIL</strong>，别的线程就能拿到锁去发下一个请求。等待是可以重叠的。</p><h2 id="为什么这么设计" tabindex="-1">为什么这么设计 <a class="header-anchor" href="#为什么这么设计" aria-label="Permalink to &quot;为什么这么设计&quot;">​</a></h2><h3 id="为什么-cpython-要有-gil" tabindex="-1">为什么 CPython 要有 GIL？ <a class="header-anchor" href="#为什么-cpython-要有-gil" aria-label="Permalink to &quot;为什么 CPython 要有 GIL？&quot;">​</a></h3><ul><li><strong>问题</strong>：CPython 用<strong>引用计数</strong>管理内存：每个对象记着「有几个变量在用我」，计数归零就释放。如果多个线程同时修改同一个计数，可能算错，导致对象被提前释放（程序崩溃）或永远不释放（内存泄漏）。</li><li><strong>方案</strong>：加一把全局大锁，同一时刻只让一个线程执行，引用计数就不会被同时修改。</li><li><strong>好处</strong>：解释器实现简单、单线程速度快，C 扩展库也更容易写对。代价是多线程无法利用多核来加速计算。</li></ul><div class="tip custom-block"><p class="custom-block-title">一句话答法</p><p>GIL 是为了保护 CPython 的引用计数等内部状态不被多线程同时修改，用一把全局锁换来实现简单和单线程性能，代价是 CPU 密集型多线程无法并行。</p></div><h3 id="为什么-io-密集用线程-cpu-密集用进程" tabindex="-1">为什么 IO 密集用线程，CPU 密集用进程？ <a class="header-anchor" href="#为什么-io-密集用线程-cpu-密集用进程" aria-label="Permalink to &quot;为什么 IO 密集用线程，CPU 密集用进程？&quot;">​</a></h3><ul><li><strong>问题</strong>：GIL 让多线程无法同时计算。</li><li><strong>方案</strong>： <ul><li><strong>IO 密集</strong>：线程在等 IO 时会释放 GIL，多个等待可以重叠 → 用<strong>多线程</strong>（或协程）。</li><li><strong>CPU 密集</strong>：每个<strong>进程</strong>有自己独立的解释器和 GIL，可以真正同时跑在多个核上 → 用<strong>多进程</strong>。</li></ul></li><li><strong>好处</strong>：两类任务都能用上合适的并发方式。代价是进程更重：创建慢、不共享内存，数据要在进程之间传递。</li></ul><div class="tip custom-block"><p class="custom-block-title">一句话答法</p><p>IO 等待时会释放 GIL，所以 IO 密集用多线程有效；CPU 密集用多进程，每个进程有独立的 GIL，能真正利用多核。</p></div><h2 id="怎么选-线程、进程、协程" tabindex="-1">怎么选：线程、进程、协程 <a class="header-anchor" href="#怎么选-线程、进程、协程" aria-label="Permalink to &quot;怎么选：线程、进程、协程&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>推荐</th><th>原因</th></tr></thead><tbody><tr><td>并发调用很多 API（比如批量调大模型）</td><td>协程（asyncio）或多线程</td><td>IO 密集，等待可以重叠；协程开销更小，见<a href="/study-hub/bagu/python/04">第 04 篇</a></td></tr><tr><td>数据处理、数值计算</td><td>多进程，或用 NumPy 等库</td><td>CPU 密集；NumPy 底层是 C 代码，计算时会释放 GIL</td></tr><tr><td>简单脚本</td><td>单线程</td><td>别过早优化</td></tr></tbody></table><h2 id="英文术语拆解" tabindex="-1">英文术语拆解 <a class="header-anchor" href="#英文术语拆解" aria-label="Permalink to &quot;英文术语拆解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>拆开看</th><th>一句话意思</th></tr></thead><tbody><tr><td>GIL</td><td>Global 全局 + Interpreter 解释器 + Lock 锁</td><td>全局解释器锁</td></tr><tr><td>CPython</td><td>C 语言实现的 Python</td><td>官方、最常用的 Python 解释器</td></tr><tr><td>Reference Counting</td><td>reference 引用 + counting 计数</td><td>引用计数：记录对象被引用了几次</td></tr><tr><td>CPU-bound</td><td>CPU + bound 受限于</td><td>CPU 密集型：时间主要花在计算上</td></tr><tr><td>IO-bound</td><td>IO（输入输出）+ bound</td><td>IO 密集型：时间主要花在等待网络、磁盘上</td></tr><tr><td>threading</td><td>thread 线程 + -ing</td><td>Python 的多线程标准库</td></tr><tr><td>multiprocessing</td><td>multi 多 + processing 处理（进程）</td><td>Python 的多进程标准库</td></tr></tbody></table><h2 id="面试怎么问" tabindex="-1">面试怎么问 <a class="header-anchor" href="#面试怎么问" aria-label="Permalink to &quot;面试怎么问&quot;">​</a></h2><p><strong>Q：Python 有 GIL，多线程还有用吗？</strong></p><blockquote><p>有用，适合 IO 密集型任务。线程在等待网络、磁盘时会释放 GIL，其他线程可以继续执行，所以多个 IO 等待能重叠。CPU 密集型任务因为 GIL 无法并行，要用多进程，或者用在计算时会释放 GIL 的 C 扩展（如 NumPy）。</p></blockquote><p><strong>Q：为什么会有 GIL？</strong></p><blockquote><p>CPython 用引用计数管理内存，GIL 保证同一时刻只有一个线程执行字节码，避免引用计数等内部状态的竞争，使解释器实现简单、单线程性能好。</p></blockquote><p><strong>Q：GIL 会被去掉吗？</strong></p><blockquote><p>Python 3.13 起提供了实验性的「自由线程」（无 GIL）构建版本，但默认版本仍然有 GIL，生态还在适配中。实际开发中仍按「IO 用线程或协程、CPU 用进程」来选。</p></blockquote><h2 id="容易混的地方" tabindex="-1">容易混的地方 <a class="header-anchor" href="#容易混的地方" aria-label="Permalink to &quot;容易混的地方&quot;">​</a></h2><ul><li><strong>有 GIL ≠ 不需要锁</strong>：GIL 只保证单条字节码执行时不被打断，<code>count += 1</code> 这种「读 → 加 → 写」由多条字节码组成，多线程下照样会出错，共享数据仍然要加锁。</li><li><strong>GIL 是 CPython 的特性，不是 Python 语言的规定</strong>：其他实现（如 Jython）没有 GIL。</li><li><strong>多进程不是万能的</strong>：进程间传数据要序列化，数据很大时开销可能超过并行带来的收益。</li></ul><h2 id="和其他知识的连接" tabindex="-1">和其他知识的连接 <a class="header-anchor" href="#和其他知识的连接" aria-label="Permalink to &quot;和其他知识的连接&quot;">​</a></h2><ul><li><strong>← 来自</strong> <a href="/study-hub/bagu/os/01">进程与线程</a>：进程隔离、线程共享内存，所以 GIL 只锁同一进程内的线程。</li><li><strong>← 来自</strong> <a href="/study-hub/bagu/os/03">调度与并发同步</a>：GIL 本质是一把互斥锁。</li><li><strong>→ 影响</strong> <a href="/study-hub/bagu/python/04">async/await 异步编程</a>：IO 密集的另一种解法。</li></ul><h2 id="自测-3-问" tabindex="-1">自测 3 问 <a class="header-anchor" href="#自测-3-问" aria-label="Permalink to &quot;自测 3 问&quot;">​</a></h2><p><strong>Q1：用「一支麦克风」类比，解释 GIL 对 CPU 密集和 IO 密集任务的不同影响。</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>GIL 像唯一的一支麦克风。CPU 密集时大家都要一直说话，只能轮流，总时间不变；IO 密集时大家大多在等回复，等的时候把麦克风放下，别人可以用，等待时间可以重叠，所以变快。</p></details><p><strong>Q2：CPython 为什么要有 GIL？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>为了保护引用计数等解释器内部状态不被多线程同时修改（否则对象可能被提前释放或泄漏），用一把全局锁换取实现简单和单线程性能。</p></details><p><strong>Q3：要并发调用 100 次大模型 API，用什么？为什么？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>用<strong>协程（asyncio）或多线程</strong>。这是 IO 密集任务，时间主要花在等网络响应上，等待时会释放 GIL，请求可以重叠进行。协程开销更小，适合大量并发。</p></details><h2 id="✅-验收清单" tabindex="-1">✅ 验收清单 <a class="header-anchor" href="#✅-验收清单" aria-label="Permalink to &quot;✅ 验收清单&quot;">​</a></h2><ul><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="0"> 能用一句话说清 GIL 是什么</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="1"> 能用「麦克风」类比解释为什么 IO 密集用线程有效、CPU 密集无效</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="2"> 能讲清 GIL 存在的原因（问题 → 方案 → 好处 / 代价）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="3"> 能根据任务类型，选择线程、进程或协程，并说出理由</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="4"> 能解释「有 GIL 为什么还需要加锁」</li></ul><h2 id="下一步该懂什么" tabindex="-1">下一步该懂什么 <a class="header-anchor" href="#下一步该懂什么" aria-label="Permalink to &quot;下一步该懂什么&quot;">​</a></h2><ul><li>处理大文件、大批数据时，怎么不一次性占满内存？→ <a href="/study-hub/bagu/python/02">迭代器、生成器与 yield</a></li></ul>',48)])])}const b=a(l,[["render",n]]);export{g as __pageData,b as default};
